package org.freecad.mobilelab;
import org.json.*;
import java.io.*;
import java.nio.file.*;
public final class MilestoneRegression {
    interface Action{void run()throws Exception;}static int checks;
    static void check(boolean b,String s){if(!b)throw new AssertionError(s);checks++;}
    static void near(double a,double b){check(Math.abs(a-b)<1e-5,"Expected "+b+", got "+a);}
    static void reject(Action a)throws Exception{try{a.run();}catch(Exception e){checks++;return;}throw new AssertionError("Invalid input accepted");}
    static void tx(Action a)throws Exception{NativeCad.beginTransaction(true);try{a.run();NativeCad.commitTransaction();}catch(Throwable t){NativeCad.rollbackTransaction();throw t;}}
    static JSONObject object(int id)throws Exception{JSONArray a=new JSONArray(NativeCad.objects());for(int i=0;i<a.length();i++)if(a.getJSONObject(i).getInt("id")==id)return a.getJSONObject(i);throw new AssertionError("Missing object "+id);}
    public static void main(String[] args)throws Exception{
        NativeCad.clear();final int box=NativeCad.create("Box",new double[]{20,10,4});tx(()->{NativeCad.properties(box,"Can's \"ring\"\nÖlçü","Jewellery",false);NativeCad.setWorkspace("{\"graphObjectIds\":[],\"tag\":\"first\"}");});String original=NativeCad.objects();check(object(box).getString("name").equals("Can's \"ring\"\nÖlçü"),"Escaped name JSON");check(object(box).getJSONArray("bbox").length()==6,"Picking bounds absent");
        tx(()->{NativeCad.move(box,7,2,1);NativeCad.setWorkspace("{\"graphObjectIds\":[],\"tag\":\"second\"}");});check(NativeCad.undo(),"Undo failed");check(NativeCad.objects().equals(original),"Undo geometry/properties mismatch");check(NativeCad.getWorkspace().contains("first"),"Recipe Undo mismatch");check(NativeCad.redo(),"Redo failed");near(object(box).getJSONArray("xyz").getDouble(0),7);check(NativeCad.getWorkspace().contains("second"),"Recipe Redo mismatch");
        check(NativeCad.undo(),"Second Undo failed");reject(()->tx(()->NativeCad.scale(box,-2)));check(NativeCad.redo(),"Failed edit destroyed Redo");check(NativeCad.undo(),"Third Undo failed");tx(()->NativeCad.move(box,2,0,0));check(!NativeCad.redo(),"New successful edit did not clear Redo");
        tx(()->NativeCad.properties(box,"Locked","Jewellery",true));String locked=NativeCad.objects();reject(()->tx(()->NativeCad.move(box,9,0,0)));reject(()->tx(()->NativeCad.scale(box,2)));reject(()->tx(()->NativeCad.rotate(box,0,0,90)));reject(()->tx(()->NativeCad.remove(box)));check(locked.equals(NativeCad.objects()),"Locked geometry changed");check(NativeCad.pick(new double[]{2,0,100,0,0,-1,.1})==0,"Locked object selectable in viewport");NativeCad.properties(box,"Unlocked","Jewellery",false);check(NativeCad.pick(new double[]{2,0,100,0,0,-1,.1})==box,"Exact CAD ray selection failed");check(NativeCad.pick(new double[]{100,100,100,0,0,-1,.1})==0,"Miss selected a CAD object");
        MeshFrame frame=new MeshFrame(NativeCad.mesh(box),NativeCad.lines(box));for(String view:new String[]{"Top","Front","Right","Back","Bottom"}){float[] a=CameraMath.preset(view);double[] ray=CameraMath.ray(frame,400,400,a[0],a[1],1,0,0,true,200,200);check(NativeCad.pick(ray)==box,"Orthographic camera picking: "+view);SoftwareRasterizer.Image image=SoftwareRasterizer.render(frame,400,400,a[0],a[1],1,0,0,true);int pixels=0;for(int c:image.pixels)if(c!=SoftwareRasterizer.BACKGROUND)pixels++;check(pixels>100,"Empty orthographic view: "+view);}
        NativeCad.visible(box,false);int curve=NativeCad.curve("Polyline",new double[]{-10,0,0,1,10,0,0,1},false,0);check(NativeCad.pick(new double[]{0,0,100,0,0,-1,.1})==curve,"Curve ray selection failed");int subd=NativeCad.create("Subdivision form",new double[]{10,10,10,2,1,0});NativeCad.visible(curve,false);NativeCad.meshAtDetail(subd,10000);check(NativeCad.pick(new double[]{0,0,100,0,0,-1,.1})==subd,"Mesh preview ray selection failed");
        File root=Files.createTempDirectory("mobile-editing-").toFile(),cache=new File(root,"cache");cache.mkdir();try{File f=new File(root,"test.fcml");ProjectStore.save(f,cache);tx(()->ProjectStore.restore(f,cache));JSONArray a=new JSONArray(NativeCad.objects());check(a.getJSONObject(0).getString("name").equals("Unlocked"),"Saved object name lost");check(a.getJSONObject(0).getString("layer").equals("Jewellery"),"Saved layer lost");check(cache.list().length==0,"Temporary files leaked");}finally{ArchiveIO.deleteTree(root);}
        System.out.println("PASS: "+checks+" milestone assertions: Redo/recipe state, lock enforcement, naming/layers, CAD/curve/mesh picking, orthographic views and persistence");
    }
}
